# region imports
from AlgorithmImports import *
import math
# endregion


class Lot:
    """A private lot of shares owned by a single strategy slot."""

    def __init__(self, symbol):
        self.symbol = symbol
        self.shares = 0          # filled shares currently owned by this lot
        self.pending = 0         # signed quantity of an outstanding order for this lot
        self.open_order_id = None

    @property
    def is_empty(self):
        return self.shares == 0 and self.pending == 0

    @property
    def is_open(self):
        return self.shares > 0

    @property
    def is_busy(self):
        return self.pending != 0


class TwoSlotParallelSystem(QCAlgorithm):
    """
    One template, 2 slots, no gate. Both slots run independently in parallel.

      Slot 1 - Strategy A (SPY): buy on close crossing above its SMA (40% of TPV),
                                 sell on close crossing below its SMA (liquidate lot).
      Slot 2 - Strategy B (AAPL): buy $20,000 after 3 consecutive red days (cash permitting),
                                  sell when 14-day RSI closes above 60 (liquidate lot).
    """

    SMA_PERIOD = 200
    RSI_PERIOD = 14
    A_ALLOCATION = 0.40
    B_DOLLARS = 20000.0
    B_RED_DAYS = 3
    B_RSI_LEVEL = 60.0

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1000000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = []
        for ticker in self.tickers:
            equity = self.add_equity(ticker, Resolution.DAILY)
            equity.set_data_normalization_mode(DataNormalizationMode.ADJUSTED)
            self.symbols.append(equity.symbol)

        self.spy = self.symbols[0]
        self.aapl = self.symbols[1]

        # ---- market-state quantities (always updated from data, never gated) ----
        self.spy_sma = self.sma(self.spy, self.SMA_PERIOD, Resolution.DAILY)
        self.aapl_rsi = self.rsi(self.aapl, self.RSI_PERIOD, MovingAverageType.WILDERS, Resolution.DAILY)

        # rolling closes: index 0 == most recent completed bar for that symbol
        self.closes = {symbol: RollingWindow[float](self.B_RED_DAYS + 1) for symbol in self.symbols}

        # previous-bar values needed for cross detection (SPY close vs SPY SMA)
        self.prev_spy_close = None
        self.prev_spy_sma = None

        # ---- slot lots ----
        self.lot_a = Lot(self.spy)
        self.lot_b = Lot(self.aapl)
        self.lots = {}  # order id -> lot

        self.set_warm_up(self.SMA_PERIOD + self.B_RED_DAYS + 5, Resolution.DAILY)

    # ------------------------------------------------------------------ #
    # main daily evaluation
    # ------------------------------------------------------------------ #
    def on_data(self, slice: Slice):
        bars = {}
        for symbol in self.symbols:
            bar = slice.bars.get(symbol) if slice.bars.contains_key(symbol) else None
            if bar is not None:
                bars[symbol] = bar

        # snapshot of yesterday's state, taken before today's state is folded in
        prev_spy_close = self.prev_spy_close
        prev_spy_sma = self.prev_spy_sma

        # market state is computed continuously, regardless of whether rules run
        for symbol, bar in bars.items():
            self.closes[symbol].add(float(bar.close))

        spy_bar = bars.get(self.spy)
        spy_sma_now = float(self.spy_sma.current.value) if self.spy_sma.is_ready else None
        if spy_bar is not None:
            self.prev_spy_close = float(spy_bar.close)
            self.prev_spy_sma = spy_sma_now

        # rule evaluation requires a bar for every subscribed ticker
        if len(bars) != len(self.symbols):
            return

        if self.is_warming_up:
            return

        if not self.indicators_ready():
            return

        if prev_spy_close is None or prev_spy_sma is None:
            return

        spy_close = float(bars[self.spy].close)
        aapl_close = float(bars[self.aapl].close)
        rsi_now = float(self.aapl_rsi.current.value)

        # ---------------- sells before buys ----------------
        # Strategy A sell: SPY close crosses below its SMA
        if self.lot_a.is_open and not self.lot_a.is_busy:
            crossed_below = prev_spy_close >= prev_spy_sma and spy_close < spy_sma_now
            if crossed_below:
                self.close_lot(self.lot_a, "A: SPY crossed below SMA")

        # Strategy B sell: AAPL 14-day RSI closes above 60
        if self.lot_b.is_open and not self.lot_b.is_busy:
            if rsi_now > self.B_RSI_LEVEL:
                self.close_lot(self.lot_b, "B: AAPL RSI above 60")

        # ---------------- buys ----------------
        # Strategy A buy: SPY close crosses above its SMA -> 40% of total portfolio value
        if self.lot_a.is_empty:
            crossed_above = prev_spy_close <= prev_spy_sma and spy_close > spy_sma_now
            if crossed_above and spy_close > 0:
                quantity = int(math.floor(self.A_ALLOCATION * float(self.portfolio.total_portfolio_value) / spy_close))
                if quantity > 0:
                    self.open_lot(self.lot_a, quantity, "A: SPY crossed above SMA")

        # Strategy B buy: AAPL red for 3 consecutive days -> $20,000 if cash allows
        if self.lot_b.is_empty:
            if self.is_red_streak(self.aapl, self.B_RED_DAYS) and aapl_close > 0:
                available_cash = float(self.portfolio.cash_book[self.account_currency].amount)
                if available_cash >= self.B_DOLLARS:
                    quantity = int(math.floor(self.B_DOLLARS / aapl_close))
                    if quantity > 0:
                        self.open_lot(self.lot_b, quantity, "B: AAPL 3 red days")

    # ------------------------------------------------------------------ #
    # helpers
    # ------------------------------------------------------------------ #
    def indicators_ready(self):
        if not (self.spy_sma.is_ready and self.aapl_rsi.is_ready):
            return False
        for window in self.closes.values():
            if not window.is_ready:
                return False
        return True

    def is_red_streak(self, symbol, days):
        """True when the last `days` bars each closed strictly below the prior close."""
        window = self.closes[symbol]
        if window.count < days + 1:
            return False
        for i in range(days):
            if not window[i] < window[i + 1]:
                return False
        return True

    def open_lot(self, lot, quantity, tag):
        ticket = self.market_order(lot.symbol, quantity, tag=tag)
        if ticket is None:
            return
        lot.pending = quantity
        lot.open_order_id = ticket.order_id
        self.lots[ticket.order_id] = lot

    def close_lot(self, lot, tag):
        if lot.shares <= 0:
            return
        ticket = self.market_order(lot.symbol, -lot.shares, tag=tag)
        if ticket is None:
            return
        lot.pending = -lot.shares
        lot.open_order_id = ticket.order_id
        self.lots[ticket.order_id] = lot

    def on_order_event(self, order_event: OrderEvent):
        lot = self.lots.get(order_event.order_id)
        if lot is None:
            return

        if order_event.status == OrderStatus.FILLED:
            lot.shares += int(order_event.fill_quantity)
            if lot.shares < 0:
                lot.shares = 0
            lot.pending = 0
            lot.open_order_id = None
            self.lots.pop(order_event.order_id, None)
        elif order_event.status == OrderStatus.PARTIALLY_FILLED:
            lot.shares += int(order_event.fill_quantity)
            lot.pending -= int(order_event.fill_quantity)
        elif order_event.status in (OrderStatus.CANCELED, OrderStatus.INVALID):
            lot.pending = 0
            lot.open_order_id = None
            self.lots.pop(order_event.order_id, None)

