# region imports
from AlgorithmImports import *
import math
# endregion


class TwoSlotParallelTemplateAlgorithm(QCAlgorithm):
    """
    One template, 2 slots, no gate. Both slots run independently in parallel.

      Slot 1 - Strategy A (SPY):
        BUY  : SPY close crosses above its simple moving average
        BUY  $: invest 40% of total portfolio value
        SELL : SPY close crosses below its simple moving average
        SELL $: liquidate Strategy A's entire lot

      Slot 2 - Strategy B (AAPL):
        BUY  : AAPL red 3 consecutive days
        BUY  $: buy $20,000 of AAPL if at least $20,000 cash available, else do nothing
        SELL : AAPL 14-day RSI closes above 60
        SELL $: liquidate Strategy B's entire lot
    """

    # ---- strategy parameters -------------------------------------------------
    SMA_PERIOD = 200            # period for "its simple moving average"
    RSI_PERIOD = 14
    RSI_SELL_LEVEL = 60.0
    RED_DAYS_REQUIRED = 3
    SLOT_A_ALLOCATION = 0.40    # 40% of total portfolio value
    SLOT_B_CASH = 20000.0       # dollars per Strategy B entry

    # =========================================================================
    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1000000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {}
        for ticker in self.tickers:
            equity = self.add_equity(ticker, Resolution.DAILY)
            equity.set_data_normalization_mode(DataNormalizationMode.ADJUSTED)
            self.symbols[ticker] = equity.symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        # ---- indicators (always updated continuously from data) -------------
        self.spy_sma = self.sma(self.spy, self.SMA_PERIOD, Resolution.DAILY)
        self.aapl_rsi = self.rsi(self.aapl, self.RSI_PERIOD,
                                 MovingAverageType.WILDERS, Resolution.DAILY)

        # ---- continuously maintained market state ---------------------------
        self.prev_close = {}            # symbol -> yesterday's close
        self.prev_sma_spy = None        # yesterday's SPY SMA value
        self.aapl_red_streak = 0        # consecutive red days for AAPL
        self.bar_count = {ticker: 0 for ticker in self.tickers}

        # ---- private lots (one per slot) ------------------------------------
        self.lot_a = 0                  # Strategy A shares of SPY
        self.lot_b = 0                  # Strategy B shares of AAPL
        self.pending_a = False          # unfilled Strategy A order outstanding
        self.pending_b = False          # unfilled Strategy B order outstanding
        self.order_owner = {}           # order id -> ("A"/"B", signed quantity)

        self.set_benchmark(self.spy)

    # =========================================================================
    def on_data(self, slice):
        bars = self._collect_bars(slice)

        # Market-state quantities are computed from data continuously.
        self._update_market_state(bars)

        try:
            if self.is_warming_up:
                return

            # If today's bar is missing for ANY subscribed ticker, skip all rules.
            if any(bar is None for bar in bars.values()):
                return

            if not self._indicators_ready():
                return

            spy_close = bars["SPY"].close
            aapl_close = bars["AAPL"].close
            sma_today = self.spy_sma.current.value
            sma_yday = self.prev_sma_spy
            spy_close_yday = self.prev_close[self.spy]

            # ------------- SELLS FIRST (every slot) --------------------------

            # Slot 1 - Strategy A sell: close crosses BELOW the SMA.
            if self.lot_a > 0 and not self.pending_a:
                crossed_below = (spy_close_yday >= sma_yday) and (spy_close < sma_today)
                if crossed_below:
                    self._submit("A", self.spy, -self.lot_a, "A: SELL cross below SMA")

            # Slot 2 - Strategy B sell: 14-day RSI closes above 60.
            if self.lot_b > 0 and not self.pending_b:
                if self.aapl_rsi.current.value > self.RSI_SELL_LEVEL:
                    self._submit("B", self.aapl, -self.lot_b, "B: SELL RSI > 60")

            # ------------- THEN BUYS -----------------------------------------

            # Slot 1 - Strategy A buy: close crosses ABOVE the SMA.
            if self.lot_a == 0 and not self.pending_a:
                crossed_above = (spy_close_yday <= sma_yday) and (spy_close > sma_today)
                if crossed_above:
                    target_value = self.SLOT_A_ALLOCATION * self.portfolio.total_portfolio_value
                    quantity = int(math.floor(target_value / spy_close))
                    if quantity > 0:
                        self._submit("A", self.spy, quantity, "A: BUY cross above SMA")

            # Slot 2 - Strategy B buy: red for 3 consecutive days.
            if self.lot_b == 0 and not self.pending_b:
                if self.aapl_red_streak >= self.RED_DAYS_REQUIRED:
                    if self.portfolio.cash >= self.SLOT_B_CASH:
                        quantity = int(math.floor(self.SLOT_B_CASH / aapl_close))
                        if quantity > 0:
                            self._submit("B", self.aapl, quantity, "B: BUY 3 red days")
                    # otherwise: do nothing this bar, stay flat

        finally:
            # Roll "yesterday" values forward for every ticker that printed today.
            self._store_previous(bars)

    # =========================================================================
    # helpers
    # =========================================================================
    def _collect_bars(self, slice):
        bars = {}
        for ticker, symbol in self.symbols.items():
            bar = None
            if slice.bars.contains_key(symbol):
                candidate = slice.bars[symbol]
                if candidate is not None and candidate.close > 0:
                    bar = candidate
            bars[ticker] = bar
        return bars

    def _update_market_state(self, bars):
        for ticker, bar in bars.items():
            if bar is not None:
                self.bar_count[ticker] += 1

        # AAPL consecutive red-day streak (close strictly below previous close).
        aapl_bar = bars["AAPL"]
        if aapl_bar is not None and self.aapl in self.prev_close:
            if aapl_bar.close < self.prev_close[self.aapl]:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

    def _store_previous(self, bars):
        for ticker, bar in bars.items():
            if bar is not None:
                self.prev_close[self.symbols[ticker]] = bar.close
        if bars["SPY"] is not None and self.spy_sma.is_ready:
            self.prev_sma_spy = self.spy_sma.current.value

    def _indicators_ready(self):
        if not (self.spy_sma.is_ready and self.aapl_rsi.is_ready):
            return False
        if self.prev_sma_spy is None:
            return False
        if self.spy not in self.prev_close or self.aapl not in self.prev_close:
            return False
        # need enough AAPL history for a fully formed 3-day red streak
        if self.bar_count["AAPL"] <= self.RED_DAYS_REQUIRED:
            return False
        return True

    def _submit(self, slot, symbol, quantity, tag):
        if quantity == 0:
            return
        ticket = self.market_order(symbol, quantity, tag=tag)
        if ticket is None:
            return
        self.order_owner[ticket.order_id] = (slot, quantity)
        if slot == "A":
            self.pending_a = True
        else:
            self.pending_b = True

    def on_order_event(self, order_event):
        owner = self.order_owner.get(order_event.order_id)
        if owner is None:
            return
        slot, intended = owner

        if order_event.status == OrderStatus.FILLED:
            filled = int(order_event.fill_quantity)
            if slot == "A":
                self.lot_a = max(0, self.lot_a + filled)
                self.pending_a = False
            else:
                self.lot_b = max(0, self.lot_b + filled)
                self.pending_b = False
            self.order_owner.pop(order_event.order_id, None)

        elif order_event.status in (OrderStatus.CANCELED, OrderStatus.INVALID):
            if slot == "A":
                self.pending_a = False
            else:
                self.pending_b = False
            self.order_owner.pop(order_event.order_id, None)

